define([],function(){let detector=null;let modelLoaded=false;let isLoading=false;let config={};let frameCounter=0;let violationCounter=0;let smoothed={yaw:0,pitch:0,roll:0,irisX:0,irisY:0};let hasSmoothedBaseline=false;let currentState={isViolation:false,direction:"center",yaw:0,pitch:0,roll:0,irisOffsetX:0,irisOffsetY:0,eyesOpen:true,faceDetected:false,violationCount:0};const LANDMARKS={NOSE_TIP:1,CHIN:152,LEFT_EYE_OUTER:33,RIGHT_EYE_OUTER:263,LEFT_MOUTH:61,RIGHT_MOUTH:291,FOREHEAD:10,LEFT_IRIS_CENTER:468,LEFT_IRIS_RIGHT:469,LEFT_IRIS_TOP:470,LEFT_IRIS_LEFT:471,LEFT_IRIS_BOTTOM:472,RIGHT_IRIS_CENTER:473,RIGHT_IRIS_RIGHT:474,RIGHT_IRIS_TOP:475,RIGHT_IRIS_LEFT:476,RIGHT_IRIS_BOTTOM:477};const LEFT_EYE={OUTER:33,INNER:133,UPPER_1:159,UPPER_2:158,LOWER_1:145,LOWER_2:153};const RIGHT_EYE={OUTER:263,INNER:362,UPPER_1:386,UPPER_2:385,LOWER_1:374,LOWER_2:380};const DEFAULT_YAW_THRESHOLD=30;const DEFAULT_PITCH_UP_THRESHOLD=20;const DEFAULT_PITCH_DOWN_THRESHOLD=15;const DEFAULT_PERSISTENCE_THRESHOLD=3;const DEFAULT_EMA_ALPHA=.4;const EAR_THRESHOLD=.2;const IRIS_TO_ANGLE_SCALE=15;const HEAD_WEIGHT=.7;const IRIS_WEIGHT=.3;function dist(a,b){return Math.sqrt(Math.pow(a.x-b.x,2)+Math.pow(a.y-b.y,2))}function clamp(val,min,max){return Math.max(min,Math.min(max,val))}function toDeg(rad){return rad*(180/Math.PI)}function ema(current,previous,alpha){return alpha*current+(1-alpha)*previous}function estimateHeadPose(keypoints){var noseTip=keypoints[LANDMARKS.NOSE_TIP];var chin=keypoints[LANDMARKS.CHIN];var leftEyeOuter=keypoints[LANDMARKS.LEFT_EYE_OUTER];var rightEyeOuter=keypoints[LANDMARKS.RIGHT_EYE_OUTER];var leftMouth=keypoints[LANDMARKS.LEFT_MOUTH];var rightMouth=keypoints[LANDMARKS.RIGHT_MOUTH];var forehead=keypoints[LANDMARKS.FOREHEAD];var faceCenterX=(leftEyeOuter.x+rightEyeOuter.x)/2;var faceWidth=dist(leftEyeOuter,rightEyeOuter);if(faceWidth<1e-4){return{yaw:0,pitch:0,roll:0}}var noseOffset=noseTip.x-faceCenterX;var yawRatio=noseOffset/(faceWidth/2);var yaw=toDeg(Math.asin(clamp(yawRatio,-1,1)));var eyeMidY=(leftEyeOuter.y+rightEyeOuter.y)/2;var noseToEye=noseTip.y-eyeMidY;var noseToChin=chin.y-noseTip.y;if(noseToChin<1e-4){return{yaw:yaw,pitch:0,roll:0}}var pitchRatio=noseToEye/noseToChin;var normalPitchRatio=.6;var pitchDeviation=pitchRatio-normalPitchRatio;var pitch=toDeg(Math.atan(pitchDeviation))*2.5;var dx=rightEyeOuter.x-leftEyeOuter.x;var dy=rightEyeOuter.y-leftEyeOuter.y;var roll=toDeg(Math.atan2(dy,dx));return{yaw:yaw,pitch:pitch,roll:roll}}function calculateEAR(keypoints,eyeIndices){var outer=keypoints[eyeIndices.OUTER];var inner=keypoints[eyeIndices.INNER];var upper1=keypoints[eyeIndices.UPPER_1];var upper2=keypoints[eyeIndices.UPPER_2];var lower1=keypoints[eyeIndices.LOWER_1];var lower2=keypoints[eyeIndices.LOWER_2];var eyeWidth=dist(outer,inner);if(eyeWidth<1e-4){return.3}var v1=dist(upper1,lower1);var v2=dist(upper2,lower2);return(v1+v2)/(2*eyeWidth)}function calculateIrisOffset(keypoints){if(keypoints.length<478){return null}var leftIrisCenter=keypoints[LANDMARKS.LEFT_IRIS_CENTER];var leftEyeOuter=keypoints[LEFT_EYE.OUTER];var leftEyeInner=keypoints[LEFT_EYE.INNER];var leftEyeUpper=keypoints[LEFT_EYE.UPPER_1];var leftEyeLower=keypoints[LEFT_EYE.LOWER_1];var leftEyeCenterX=(leftEyeOuter.x+leftEyeInner.x)/2;var leftEyeCenterY=(leftEyeUpper.y+leftEyeLower.y)/2;var leftEyeWidth=dist(leftEyeOuter,leftEyeInner);var leftEyeHeight=dist(leftEyeUpper,leftEyeLower);var rightIrisCenter=keypoints[LANDMARKS.RIGHT_IRIS_CENTER];var rightEyeOuter=keypoints[RIGHT_EYE.OUTER];var rightEyeInner=keypoints[RIGHT_EYE.INNER];var rightEyeUpper=keypoints[RIGHT_EYE.UPPER_1];var rightEyeLower=keypoints[RIGHT_EYE.LOWER_1];var rightEyeCenterX=(rightEyeOuter.x+rightEyeInner.x)/2;var rightEyeCenterY=(rightEyeUpper.y+rightEyeLower.y)/2;var rightEyeWidth=dist(rightEyeOuter,rightEyeInner);var rightEyeHeight=dist(rightEyeUpper,rightEyeLower);if(leftEyeWidth<1e-4||leftEyeHeight<1e-4||rightEyeWidth<1e-4||rightEyeHeight<1e-4){return null}var leftOffsetX=(leftIrisCenter.x-leftEyeCenterX)/(leftEyeWidth/2);var leftOffsetY=(leftIrisCenter.y-leftEyeCenterY)/(leftEyeHeight/2);var rightOffsetX=(rightIrisCenter.x-rightEyeCenterX)/(rightEyeWidth/2);var rightOffsetY=(rightIrisCenter.y-rightEyeCenterY)/(rightEyeHeight/2);return{x:(leftOffsetX+rightOffsetX)/2,y:(leftOffsetY+rightOffsetY)/2}}function fuseGaze(headPose,irisOffset){var yawThreshold=config.gazeYawThreshold||DEFAULT_YAW_THRESHOLD;var pitchUpThreshold=config.gazePitchUpThreshold||DEFAULT_PITCH_UP_THRESHOLD;var pitchDownThreshold=config.gazePitchDownThreshold||DEFAULT_PITCH_DOWN_THRESHOLD;var effectiveYaw=headPose.yaw;var effectivePitch=headPose.pitch;if(irisOffset){var irisYawContribution=irisOffset.x*IRIS_TO_ANGLE_SCALE;var irisPitchContribution=irisOffset.y*IRIS_TO_ANGLE_SCALE;effectiveYaw=headPose.yaw*HEAD_WEIGHT+irisYawContribution*IRIS_WEIGHT;effectivePitch=headPose.pitch*HEAD_WEIGHT+irisPitchContribution*IRIS_WEIGHT}var direction="center";var isLookingAway=false;if(Math.abs(effectiveYaw)>yawThreshold){direction=effectiveYaw>0?"right":"left";isLookingAway=true}else if(effectivePitch>pitchUpThreshold){direction="down";isLookingAway=true}else if(effectivePitch<-pitchDownThreshold){direction="up";isLookingAway=true}return{isLookingAway:isLookingAway,direction:direction,effectiveYaw:effectiveYaw,effectivePitch:effectivePitch}}async function init(cfg){config=cfg;if(isLoading||modelLoaded){return modelLoaded}isLoading=true;try{if(typeof tf==="undefined"){throw new Error("TensorFlow.js not loaded")}if(typeof faceLandmarksDetection==="undefined"){throw new Error("face-landmarks-detection library not loaded")}await tf.ready();console.log("[Proctor GazeTracker] TF.js backend:",tf.getBackend());var detectorConfig={runtime:"tfjs",refineLandmarks:true,maxFaces:1,landmarkModelUrl:config.faceMeshLandmarkModelUrl,detectorModelUrl:config.faceMeshDetectorModelUrl};detector=await faceLandmarksDetection.createDetector(faceLandmarksDetection.SupportedModels.MediaPipeFaceMesh,detectorConfig);modelLoaded=true;isLoading=false;console.log("[Proctor GazeTracker] MediaPipe FaceMesh model loaded (478 landmarks + iris)");return true}catch(err){console.error("[Proctor GazeTracker] Failed to load FaceMesh model:",err);modelLoaded=false;isLoading=false;return false}}async function analyze(videoEl){if(!modelLoaded||!detector){return currentState}if(!videoEl||videoEl.paused||videoEl.ended||!videoEl.videoWidth){return currentState}try{var faces=await detector.estimateFaces(videoEl,{flipHorizontal:false,staticImageMode:false});if(!faces||faces.length===0){currentState.faceDetected=false;return currentState}var keypoints=faces[0].keypoints;currentState.faceDetected=true;if(!keypoints||keypoints.length<468){return currentState}var leftEAR=calculateEAR(keypoints,LEFT_EYE);var rightEAR=calculateEAR(keypoints,RIGHT_EYE);var avgEAR=(leftEAR+rightEAR)/2;currentState.eyesOpen=avgEAR>=EAR_THRESHOLD;frameCounter++;if(frameCounter%10===0){console.log("[Proctor Debug] EAR values:",{leftEAR:leftEAR,rightEAR:rightEAR,avgEAR:avgEAR,eyesOpen:currentState.eyesOpen})}if(!currentState.eyesOpen){return currentState}var headPose=estimateHeadPose(keypoints);var irisOffset=null;if(keypoints.length>=478){irisOffset=calculateIrisOffset(keypoints)}var alpha=config.gazeEmaAlpha||DEFAULT_EMA_ALPHA;if(!hasSmoothedBaseline){smoothed.yaw=headPose.yaw;smoothed.pitch=headPose.pitch;smoothed.roll=headPose.roll;smoothed.irisX=irisOffset?irisOffset.x:0;smoothed.irisY=irisOffset?irisOffset.y:0;hasSmoothedBaseline=true}else{smoothed.yaw=ema(headPose.yaw,smoothed.yaw,alpha);smoothed.pitch=ema(headPose.pitch,smoothed.pitch,alpha);smoothed.roll=ema(headPose.roll,smoothed.roll,alpha);if(irisOffset){smoothed.irisX=ema(irisOffset.x,smoothed.irisX,alpha);smoothed.irisY=ema(irisOffset.y,smoothed.irisY,alpha)}}var smoothedHeadPose={yaw:smoothed.yaw,pitch:smoothed.pitch,roll:smoothed.roll};var smoothedIris=irisOffset?{x:smoothed.irisX,y:smoothed.irisY}:null;var gazeResult=fuseGaze(smoothedHeadPose,smoothedIris);var persistenceThreshold=config.gazePersistenceThreshold||DEFAULT_PERSISTENCE_THRESHOLD;if(gazeResult.isLookingAway){violationCounter++}else{violationCounter=0}var isConfirmedViolation=violationCounter>=persistenceThreshold;if(violationCounter>0||frameCounter%10===0){console.log("[Proctor Gaze Debug] Head:",headPose,"Iris:",irisOffset,"Result:",gazeResult,"Count:",violationCounter)}currentState={isViolation:isConfirmedViolation,direction:gazeResult.isLookingAway?gazeResult.direction:"center",yaw:Math.round(gazeResult.effectiveYaw*10)/10,pitch:Math.round(gazeResult.effectivePitch*10)/10,roll:Math.round(smoothedHeadPose.roll*10)/10,irisOffsetX:smoothedIris?Math.round(smoothedIris.x*100)/100:0,irisOffsetY:smoothedIris?Math.round(smoothedIris.y*100)/100:0,eyesOpen:true,faceDetected:true,violationCount:violationCounter};return currentState}catch(err){console.error("[Proctor GazeTracker] Analysis error:",err);return currentState}}function getState(){return currentState}function getDirection(){return currentState.direction}function isReady(){return modelLoaded}function stop(){violationCounter=0;hasSmoothedBaseline=false;smoothed={yaw:0,pitch:0,roll:0,irisX:0,irisY:0};currentState={isViolation:false,direction:"center",yaw:0,pitch:0,roll:0,irisOffsetX:0,irisOffsetY:0,eyesOpen:true,faceDetected:false,violationCount:0};if(detector){try{detector.dispose()}catch(e){}detector=null}modelLoaded=false;isLoading=false}function formatForReport(){return currentState.direction+","+currentState.yaw+","+currentState.pitch}return{init:init,analyze:analyze,getState:getState,getDirection:getDirection,isReady:isReady,stop:stop,formatForReport:formatForReport}});